// Regenerate golden-timings.json — how long each gate file takes against the
// reference solution.
//
//   node measure-golden-timings.mjs
//
// DELIBERATELY NOT RUN BY THE BUILD. The grader's identity hash covers this
// directory, so a file that rewrote itself on every rebuild would report the
// grader as changed every time and send the operator back to Refresh grader
// forever. It is regenerated by hand when a gate file's real cost changes, and
// the numbers are reviewed in the diff like any other measurement.
//
// A file absent from the output is not an error: `report.mjs` falls back to the
// flat runner timeout for anything it has no reference time for, which is never
// stricter than the behaviour before these numbers existed.

import { execFileSync } from "node:child_process";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { fileURLToPath } from "node:url";

const HERE = path.dirname(fileURLToPath(import.meta.url));
const GOLDEN = path.resolve(HERE, "../task/backgammon/golden");

function backendFiles() {
  const root = path.join(HERE, "backend");
  const out = [];
  const walk = (dir) => {
    for (const e of fs.readdirSync(dir, { withFileTypes: true }).sort((a, b) =>
      a.name.localeCompare(b.name),
    )) {
      const full = path.join(dir, e.name);
      if (e.isDirectory()) walk(full);
      else if (e.isFile() && e.name.endsWith(".test.ts")) out.push(path.relative(HERE, full));
    }
  };
  walk(root);
  return out;
}

const timings = {};
for (const file of backendFiles()) {
  const out = path.join(os.tmpdir(), `golden-timing-${Date.now()}.json`);
  execFileSync("npx", ["vitest", "run", file, "--reporter=json", `--outputFile=${out}`], {
    cwd: HERE,
    env: { ...process.env, BENCH_TARGET: GOLDEN },
    stdio: "ignore",
  });
  const report = JSON.parse(fs.readFileSync(out, "utf8"));
  // Test execution only. Wall time is ~500ms of npx/vitest startup on this
  // machine and would drown the signal for the fast files — the startup cost
  // is allowed for separately, as a flat floor.
  const ms = (report.testResults ?? []).reduce(
    (n, s) => n + ((s.endTime ?? 0) - (s.startTime ?? 0)),
    0,
  );
  timings[file] = Math.round(ms * 100) / 100;
  fs.unlinkSync(out);
  process.stderr.write(`${file}  ${timings[file]}ms\n`);
}

fs.writeFileSync(
  path.join(HERE, "golden-timings.json"),
  JSON.stringify(
    {
      _comment:
        "Test-execution milliseconds for each gate file against the golden. "
        + "report.mjs budgets a runner at STARTUP_ALLOWANCE + this * MULTIPLIER. "
        + "Regenerate with `node measure-golden-timings.mjs`; a missing file "
        + "falls back to the flat runner timeout.",
      measured_at: new Date().toISOString(),
      files: timings,
    },
    null,
    2,
  ) + "\n",
);
process.stderr.write("wrote golden-timings.json\n");
